{
  "unit_id": "p3",
  "status": "UNRESOLVED",
  "reason": "Cross-references to parent unit (h0) and external tool documentation are unresolved. Shared conditions (e.g., identity verification) and exceptions (e.g., tool unlocking rules) require broader context.",
  "requirements": [
    {
      "local_id": "tool_unlocking_rule",
      "action": "unlock_discoverable_agent_tool",
      "action_spans": [
        {
          "source_id": "p2",
          "quote": "unlock the tool using `unlock_discoverable_agent_tool(agent_tool_name)`"
        }
      ],
      "scope": "discoverable_agent_tool",
      "source_spans": [
        {
          "source_id": "p2",
          "quote": "Only unlock a tool when the knowledge base explicitly mentions it (e.g., \"use tool_name to perform X\")"
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "Tool unlock condition",
        "spans": [
          {
            "source_id": "p2",
            "quote": "knowledge base explicitly mentions it (e.g., \"use tool_name to perform X\")"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "Tool name validation",
            "spans": [
              {
                "source_id": "p2",
                "quote": "Do not invent or guess tool names - only use tool names discovered in the knowledge base"
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "Intent validation",
            "spans": [
              {
                "source_id": "p2",
                "quote": "Do not unlock tools you do not plan to use"
              }
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "ATOM",
        "label": "Database logging guard",
        "spans": [
          {
            "source_id": "p2",
            "quote": "this causes issues in database logging"
          }
        ],
        "children": []
      },
      "exceptions": [],
      "open_questions": [
        "How are tool names explicitly mentioned in the knowledge base identified programmatically?",
        "What constitutes 'planning to use' a tool (e.g., user intent detection criteria)?",
        "Are there tool-specific unlocking rules not covered in this fragment?"
      ]
    },
    {
      "local_id": "tool_usage_sequence",
      "action": "call_discoverable_agent_tool",
      "action_spans": [
        {
          "source_id": "p2",
          "quote": "call the tool using `call_discoverable_agent_tool(agent_tool_name, arguments)`"
        }
      ],
      "scope": "discoverable_agent_tool",
      "source_spans": [
        {
          "source_id": "p2",
          "quote": "The unlock step is required before calling - you cannot call a tool that hasn't been unlocked"
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "BEFORE",
        "label": "Precondition: tool unlocked",
        "spans": [
          {
            "source_id": "p2",
            "quote": "unlock the tool before using it to get information on the proper params"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "Unlock action",
            "spans": [
              {
                "source_id": "p2",
                "quote": "unlock_discoverable_agent_tool(agent_tool_name)"
              }
            ],
            "children": []
          }
        ]
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "What are the 'proper params' for each tool, and how are they determined?",
        "Are there tools that can be called without prior unlocking (e.g., read-only tools)?"
      ]
    },
    {
      "local_id": "identity_verification_rule",
      "action": "verify_user_identity",
      "action_spans": [
        {
          "source_id": "p2",
          "quote": "verify their identity before proceeding"
        }
      ],
      "scope": "customer_information_access",
      "source_spans": [
        {
          "source_id": "p2",
          "quote": "Generally, for any scenario involving accessing customer information in internal databases, you must first verify their identity before proceeding"
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "Verification condition",
        "spans": [
          {
            "source_id": "p2",
            "quote": "you must first verify their identity before proceeding"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "Access scope",
            "spans": [
              {
                "source_id": "p2",
                "quote": "accessing customer information in internal databases"
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "Single-conversation rule",
            "spans": [
              {
                "source_id": "p2",
                "quote": "No need to verify more than once in a single conversation"
              }
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "ATOM",
        "label": "Information leakage guard",
        "spans": [
          {
            "source_id": "p2",
            "quote": "Do not leak any information about the user before they are verified"
          }
        ],
        "children": []
      },
      "exceptions": [
        {
          "op": "ATOM",
          "label": "Verification exemption",
          "spans": [
            {
              "source_id": "p2",
              "quote": "you should ONLY verify a user's identity if you need to access or modify their customer information"
            }
          ],
          "children": []
        }
      ],
      "open_questions": [
        "What constitutes 'customer information' (e.g., does it include transaction metadata)?",
        "How is 'single conversation' defined (e.g., session timeout, explicit user confirmation)?",
        "Are there tools or actions that bypass verification (e.g., public-facing tools)?"
      ]
    },
    {
      "local_id": "identity_verification_procedure",
      "action": "call_verification_tools",
      "action_spans": [
        {
          "source_id": "p2",
          "quote": "call the appropriate read tools"
        }
      ],
      "scope": "user_identity_verification",
      "source_spans": [
        {
          "source_id": "p2",
          "quote": "To verify the identity of the user, call the appropriate read tools"
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "Verification criteria",
        "spans": [
          {
            "source_id": "p2",
            "quote": "ensure that they are able to give correctly any 2 out of the following values"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "Field requirement",
            "spans": [
              {
                "source_id": "p2",
                "quote": "date of birth, email, phone number, address"
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "Field exclusions",
            "spans": [
              {
                "source_id": "p2",
                "quote": "Knowing full name or userID is not enough to verify"
              }
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "AFTER",
        "label": "Post-verification logging",
        "spans": [
          {
            "source_id": "p2",
            "quote": "you must call the verification logging tool to properly log the information into the verification records"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "Logging action",
            "spans": [
              {
                "source_id": "p3",
                "quote": "log_verification"
              }
            ],
            "children": []
          }
        ]
      },
      "exceptions": [],
      "open_questions": [
        "What tools are classified as 'appropriate read tools' for verification?",
        "How are conflicting identity values resolved (e.g., mismatched email/address)?",
        "Is there a timeout for verification attempts?"
      ]
    },
    {
      "local_id": "kb_search_language_rule",
      "action": "formulate_search_query",
      "action_spans": [
        {
          "source_id": "p3",
          "quote": "formulate knowledge base search queries"
        }
      ],
      "scope": "KB_search_bm25, KB_search_dense, grep, KB_search",
      "source_spans": [
        {
          "source_id": "p3",
          "quote": "The knowledge base documents are written in Russian. Always formulate knowledge base search queries in Russian."
        }
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "Language condition",
        "spans": [
          {
            "source_id": "p3",
            "quote": "knowledge base documents are written in Russian"
          }
        ],
        "children": []
      },
      "guard": {
        "op": "OR",
        "label": "English exceptions",
        "spans": [
          {
            "source_id": "p3",
            "quote": "Official product and account names (e.g. 'Platinum Rewards', 'Blue Account'), tool identifiers, and status codes remain in English"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "Product names",
            "spans": [
              {
                "source_id": "p3",
                "quote": "'Platinum Rewards', 'Blue Account'"
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "Tool identifiers",
            "spans": [
              {
                "source_id": "p3",
                "quote": "tool identifiers"
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "Status codes",
            "spans": [
              {
                "source_id": "p3",
                "quote": "status codes"
              }
            ],
            "children": []
          }
        ]
      },
      "exceptions": [],
      "open_questions": [
        "What is the expected accuracy threshold for Russian queries?",
        "Are there bilingual tools or hybrid search strategies supported?",
        "How are tool identifiers distinguished from regular text in queries?"
      ]
    },
    {
      "local_id": "transfer_to_human_agents",
      "action": "transfer_to_human_agents",
      "action_spans": [
        {
          "source_id": "p3",
          "quote": "transfer the user to a human agent"
        }
      ],
      "scope": "user_escalation",
      "source_spans": [
        {
          "source_id": "p3",
          "quote": "Transfer the user to a human agent"
        }
      ],
      "modality": "PERMIT",
      "condition": {
        "op": "UNKNOWN",
        "label": "Transfer condition (unresolved)",
        "spans": [
          {
            "source_id": "p3",
            "quote": "The proper transfer reason enum can be found in the knowledge base"
          }
        ],
        "children": []
      },
      "guard": {
        "op": "AND",
        "label": "Transfer prerequisites",
        "spans": [
          {
            "source_id": "p3",
            "quote": "search it before calling this tool to select the proper applicable reason"
          }
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "Reason validation",
            "spans": [
              {
                "source_id": "p3",
                "quote": "search the knowledge base to find tools that you can unlock"
              }
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "Summary requirement",
            "spans": [
              {
                "source_id": "p3",
                "quote": "summary: string! — A summary of the user's issue and what was attempted before transfer"
              }
            ],
            "children": []
          }
        ]
      },
      "exceptions": [],
      "open_questions": [
        "What are the specific 'proper transfer reason enum' values and their criteria?",
        "How is the 'summary' generated (e.g., automated or manual)?",
        "Are there automated transfer triggers (e.g., failed verification attempts)?"
      ]
    },
    {
      "local_id": "user_tool_delegation",
      "action": "give_discoverable_user_tool",
      "action_spans": [
        {
          "source_id": "p4",
          "quote": "Pass a tool to the user so they can execute it themselves"
        }
      ],
      "scope": "user-initiated_actions",
      "source_spans": [
        {
          "source_id": "p4",
          "quote": "Use this when the knowledge base indicates that the user should perform an action themselves"
        }
      ],
      "modality": "PERMIT",
      "condition": {
        "op": "ATOM",
        "label": "KB indication",
        "spans": [
          {
            "source_id": "p4",
            "quote": "the knowledge base indicates that the user should perform an action themselves"
          }
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "What constitutes 'the knowledge base indicates' (e.g., specific phrases or patterns)?",
        "How are tool arguments validated when passed to the user?",
        "Are there tools that cannot be delegated to users?"
      ]
    }
  ]
}
